from itertools import product
from typing import Dict, Hashable, List

Flag = Hashable
Involution = Dict[Flag, Flag]


def hypercube_family(dim: int):
    """sigma_i flips bit i of {0,1}^dim; flag graph is the hypercube Q_dim."""
    flags = list(product((0, 1), repeat=dim))

    def flip(i: int) -> Involution:
        s: Involution = {}
        for v in flags:
            w = list(v); w[i] ^= 1; s[v] = tuple(w)
        return s

    return flags, [flip(i) for i in range(dim)]


def verify_involution_family(flags: List[Flag], sigmas: List[Involution]):
    involutive = all(s[s[x]] == x for s in sigmas for x in flags)
    fpf = all(s[x] != x for s in sigmas for x in flags)
    string = all(
        sigmas[i][sigmas[j][x]] == sigmas[j][sigmas[i][x]]
        for i in range(len(sigmas)) for j in range(len(sigmas))
        if abs(i - j) >= 2 for x in flags)
    sep = all(
        sigmas[i][v] != sigmas[j][v]
        for v in flags for i in range(len(sigmas))
        for j in range(len(sigmas)) if i != j)
    return dict(involutive=involutive, fixed_point_free=fpf,
                string=string, separation=sep,
                valid=involutive and fpf and string and sep)


if __name__ == "__main__":
    flags, sig = hypercube_family(4)
    print("Rank-4 family on {0,1}^4:", verify_involution_family(flags, sig))

from itertools import product
from typing import Dict, Hashable, List, Set

Flag = Hashable
Involution = Dict[Flag, Flag]


def hypercube_family(dim: int):
    flags = list(product((0, 1), repeat=dim))
    def flip(i):
        s = {}
        for v in flags:
            w = list(v); w[i] ^= 1; s[v] = tuple(w)
        return s
    return flags, [flip(i) for i in range(dim)]


def degree_sequence(flags: List[Flag], sigmas: List[Involution]) -> Dict[Flag, int]:
    nb: Dict[Flag, Set[Flag]] = {v: set() for v in flags}
    for v in flags:
        for s in sigmas:
            nb[v].add(s[v]); nb[s[v]].add(v)
    return {v: len(nb[v]) for v in flags}


if __name__ == "__main__":
    # Confirm the rank-valence principle: rank n => n-regular flag graph.
    for dim in range(1, 8):
        flags, sig = hypercube_family(dim)
        degs = set(degree_sequence(flags, sig).values())
        print(f"rank {dim}: |flags|={len(flags):3d}  degree set={sorted(degs)}"
              f"  n-regular={degs == {dim}}")

from itertools import product
from typing import Dict, Hashable, List, Tuple

Flag = Hashable
Involution = Dict[Flag, Flag]


def hypercube_family(dim: int):
    flags = list(product((0, 1), repeat=dim))
    def flip(i):
        s = {}
        for v in flags:
            w = list(v); w[i] ^= 1; s[v] = tuple(w)
        return s
    return flags, [flip(i) for i in range(dim)]


def two_element_orbits(flags: List[Flag], sigma: Involution) -> List[Tuple[Flag, Flag]]:
    seen, orbits = set(), []
    for x in flags:
        if x not in seen:
            y = sigma[x]; orbits.append((x, y)); seen.update({x, y})
    return orbits


if __name__ == "__main__":
    # Each fixed-point-free involution partitions flags into pairs => even count.
    for dim in range(1, 6):
        flags, sig = hypercube_family(dim)
        orbits = two_element_orbits(flags, sig[0])
        print(f"rank {dim}: |flags|={len(flags):2d}  #pairs(sigma_0)={len(orbits)}"
              f"  even={len(flags) % 2 == 0}")
    # Observed small regular 4-maniplex flag counts are all divisible by 24.
    for c in (120, 384, 1152, 14400):
        print(f"flag count {c:5d}: divisible by 8 -> {c % 8 == 0}, "
              f"by 24 -> {c % 24 == 0}")

